CREATE TYPE "ClaseActividadEstado" AS ENUM ('PROGRAMADA','EN_CURSO','FINALIZADA','SUSPENDIDA','CANCELADA');
CREATE TABLE "ClaseActividad" ("id" TEXT NOT NULL,"horarioActividadId" TEXT NOT NULL,"fecha" DATE NOT NULL,"horaInicio" TEXT NOT NULL,"horaFin" TEXT NOT NULL,"establecimientoId" TEXT NOT NULL,"espacio" TEXT,"estado" "ClaseActividadEstado" NOT NULL DEFAULT 'PROGRAMADA',"observaciones" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ClaseActividad_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClaseActividadProfesor" ("id" TEXT NOT NULL,"claseActividadId" TEXT NOT NULL,"profesorId" UUID NOT NULL,"esPrincipal" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ClaseActividadProfesor_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ClaseActividad_horarioActividadId_fecha_key" ON "ClaseActividad"("horarioActividadId","fecha");
CREATE INDEX "ClaseActividad_horarioActividadId_idx" ON "ClaseActividad"("horarioActividadId"); CREATE INDEX "ClaseActividad_establecimientoId_idx" ON "ClaseActividad"("establecimientoId"); CREATE INDEX "ClaseActividad_fecha_idx" ON "ClaseActividad"("fecha"); CREATE INDEX "ClaseActividad_estado_idx" ON "ClaseActividad"("estado");
CREATE UNIQUE INDEX "ClaseActividadProfesor_claseActividadId_profesorId_key" ON "ClaseActividadProfesor"("claseActividadId","profesorId"); CREATE UNIQUE INDEX "ClaseActividadProfesor_one_primary" ON "ClaseActividadProfesor"("claseActividadId") WHERE "esPrincipal"=true; CREATE INDEX "ClaseActividadProfesor_claseActividadId_idx" ON "ClaseActividadProfesor"("claseActividadId"); CREATE INDEX "ClaseActividadProfesor_profesorId_idx" ON "ClaseActividadProfesor"("profesorId");
ALTER TABLE "ClaseActividad" ADD CONSTRAINT "ClaseActividad_horarioActividadId_fkey" FOREIGN KEY ("horarioActividadId") REFERENCES "ActividadHorario"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ClaseActividad" ADD CONSTRAINT "ClaseActividad_establecimientoId_fkey" FOREIGN KEY ("establecimientoId") REFERENCES "Establecimiento"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ClaseActividadProfesor" ADD CONSTRAINT "ClaseActividadProfesor_claseActividadId_fkey" FOREIGN KEY ("claseActividadId") REFERENCES "ClaseActividad"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ClaseActividadProfesor" ADD CONSTRAINT "ClaseActividadProfesor_profesorId_fkey" FOREIGN KEY ("profesorId") REFERENCES "Profesor"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "Permiso" ("modulo","accion","nombre","descripcion","activo","createdAt","updatedAt") VALUES ('activity_sessions','ver','activity_sessions:ver','Permite visualizar clases programadas.',true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('activity_sessions','crear','activity_sessions:crear','Permite crear clases programadas.',true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('activity_sessions','editar','activity_sessions:editar','Permite editar clases programadas.',true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('activity_sessions','eliminar','activity_sessions:eliminar','Permite cambiar el estado de clases programadas.',true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),('activity_sessions','asignar','activity_sessions:asignar','Permite asignar sedes y profesores.',true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT ("modulo","accion") DO UPDATE SET "nombre"=EXCLUDED."nombre","descripcion"=EXCLUDED."descripcion","activo"=true,"updatedAt"=CURRENT_TIMESTAMP;
